"""Build the public formal-experiment pages from the reviewed model/config registry."""
from pathlib import Path
import argparse
import hashlib
import json

CSS = r'''*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#182231;font:15px/1.55 system-ui,-apple-system,sans-serif}a{color:#2563eb;text-decoration:none}a:hover{text-decoration:underline}header{background:#fff;border-bottom:1px solid #dfe5ee;position:sticky;top:0;z-index:5}nav,main{max-width:1320px;margin:auto;padding:18px 26px}nav{display:flex;justify-content:space-between;align-items:center;gap:20px}nav strong{font-size:20px}nav span{display:flex;gap:22px;font-size:13px}main{padding-top:32px;padding-bottom:70px}h1{font-size:36px;line-height:1.18;letter-spacing:-1px;margin:7px 0 12px}h2{font-size:22px;margin:30px 0 14px}.eyebrow{color:#55708f;font-size:11px;font-weight:700;letter-spacing:1.5px}.muted{color:#64748b}.small{font-size:12px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin:24px 0}.card,.panel{background:#fff;border:1px solid #dfe5ee;border-radius:13px;padding:20px}.card h3{margin:12px 0 7px;font-size:18px}.num{font-size:27px;font-weight:750}.badge{display:inline-block;padding:3px 9px;border-radius:20px;font-size:11px;font-weight:650;background:#eaf0f7;color:#526479}.active{background:#e4f2ed;color:#19724e}.queued{background:#fff1d6;color:#97651a}.failed,.stale{background:#fde9e7;color:#a13230}.complete{background:#e5edfF;color:#255bb1}.table{overflow:auto;background:#fff;border:1px solid #dfe5ee;border-radius:13px}table{width:100%;border-collapse:collapse;min-width:820px}th,td{text-align:left;padding:15px;border-bottom:1px solid #e9edf3;vertical-align:top}th{background:#f9fbfd;font-size:12px;color:#65758d}tr:last-child td{border-bottom:0}.charts{display:grid;grid-template-columns:repeat(2,1fr);gap:16px;margin:20px 0}.charts figure{margin:0;background:#fff;border:1px solid #dfe5ee;border-radius:13px;padding:10px}.charts img{width:100%;display:block}.charts figcaption{font-size:12px;color:#64748b;padding:6px 4px 0}@media(max-width:800px){.charts{grid-template-columns:1fr}}tr.baseline td{background:#fbfcfe}.progress{height:5px;border-radius:8px;background:#e8edf4;margin:8px 0;overflow:hidden;min-width:90px}.progress i{display:block;height:100%;background:#3978dd}.stats{display:flex;gap:24px;flex-wrap:wrap;margin:18px 0}.stats b{display:block;font-size:23px}.casegrid{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}.case{border:1px solid #dfe5ee;border-radius:10px;background:white;overflow:hidden;cursor:pointer;text-align:left;padding:0;color:inherit}.case img{width:100%;aspect-ratio:16/9;object-fit:contain;background:#edf1f6;display:block}.case .info{padding:11px;font-size:12px}.case.selected{outline:2px solid #3978dd}.case .empty{height:80px;background:#f0f3f7;padding:18px}.detail{margin:20px 0}.versions{display:grid;grid-template-columns:repeat(2,1fr);gap:15px}.versions video,.inputimage{width:100%;max-height:420px;background:#edf1f6;border-radius:8px;object-fit:contain}pre{white-space:pre-wrap;word-break:break-word;font:12px/1.6 ui-monospace,monospace;background:#f5f7fb;padding:16px;border-radius:8px;max-height:420px;overflow:auto}details{margin:10px 0;border:1px solid #e1e6ed;padding:12px;border-radius:8px}summary{cursor:pointer;font-weight:600}.notice{border-left:3px solid #e5b14b;background:#fff7e6;padding:12px 16px;margin:18px 0}.toolbar{display:flex;justify-content:space-between;gap:15px;align-items:center;margin:22px 0}select{padding:8px;border:1px solid #dfe5ee;background:white;border-radius:6px}footer{margin-top:32px;font-size:12px;color:#8290a3}@media(max-width:1000px){.cards{grid-template-columns:repeat(2,1fr)}.casegrid{grid-template-columns:repeat(4,1fr)}}@media(max-width:650px){nav,main{padding:16px}.cards,.versions{grid-template-columns:1fr}.casegrid{grid-template-columns:repeat(2,1fr)}h1{font-size:28px}nav span{gap:12px}.toolbar{display:block}}'''

JS = r'''(()=>{const BASE=document.body.dataset.liveBase||new URL('.',location.href).href;let plan,cat,evaluation={cohorts:[]},selected=null,lastDetailKey='';const $=x=>document.getElementById(x),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const num=x=>typeof x==='number'?Math.round(x).toLocaleString():'—',tok=x=>typeof x==='number'?(x/1000).toFixed(1)+'k':'—',mins=x=>typeof x==='number'?(x/60).toFixed(1)+' min':'—',ago=x=>{if(!x)return'尚无有效交付';const s=Math.max(0,Math.floor((Date.now()-new Date(x).getTime())/1000));if(s<60)return s+' 秒前';if(s<3600)return Math.floor(s/60)+' 分钟前';if(s<86400)return Math.floor(s/3600)+' 小时前';return Math.floor(s/86400)+' 天前'},asset=(x,base=BASE)=>x?(String(x).startsWith('https://')?x:new URL(x,base).href):'';
async function load(path,local=false,detailMode=false,preferLive=false){let roots=local?[new URL('.',location.href).href]:[...(detailMode?[cat?.detail_base||BASE,'https://huggingface.co/datasets/HuggingFriends/PixelWorld/resolve/main/data/']:[]),BASE,new URL('.',location.href).href];if(!local&&cat?.live_origin){if(preferLive)roots.unshift(cat.live_origin);else roots.push(cat.live_origin)}let error;for(const base of [...new Set(roots)]){const url=new URL(path,base).href;try{const r=await fetch(url+'?t='+Date.now(),{cache:'no-store',signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error('HTTP '+r.status);const data=await r.json();data._asset_base=base;data._live_source=base===cat?.live_origin;if(data._live_source){data.live_origin=data.live_origin||cat.live_origin;data.detail_base=data.detail_base||cat.detail_base}return data}catch(e){error=e}}throw error}
function retryMedia(root){if(!cat?.live_origin)return;for(const media of root.querySelectorAll('video,img'))media.addEventListener('error',()=>{if(media.dataset.liveRetried)return;let url=media.getAttribute('src')||'';const prefix='https://huggingface.co/datasets/HuggingFriends/PixelWorld/resolve/main/data/';if(!url.startsWith(prefix))return;media.dataset.liveRetried='1';media.src=new URL(url.slice(prefix.length),cat.live_origin).href;const note=document.createElement('p');note.className='small muted';note.textContent='HF 资源同步中，当前使用实时预览。';media.after(note)})}
function groups(b){return(cat.groups||[]).filter(g=>g.suite===b.suite&&g.track===(b.track||'vision-agent'))}
function groupLink(b,key){const p=new URLSearchParams();p.set('model',key);if(b.track){p.set('suite',b.suite);p.set('track',b.track)}return b.page+'?'+p.toString()}
function state(g){if(!g)return['queued','待调度'];if(g.paused)return['queued','已暂停'];let c=g.counts||{};if(c.running)return['active',g.upstream_wait?.waiting_cases?'等待模型 / 运行中':'运行中'];if(c.pending)return['queued','队列中'];if(c.complete===g.cases_total)return['complete','已完成'];if(c.exhausted)return['failed','有终止样本'];return['queued','待调度']}
function badge(g){const[s,t]=state(g);return'<span class="badge '+s+'">'+t+'</span>'}
function cell(g,b,m){if(m.pending)return'<span class="badge queued">待确认模型</span>';const c=g?.counts||{},v=c.complete||0;return'<a href="'+groupLink(b,m.key)+'"><b>'+v+' / '+b.cases+(g?.completion_exceptions?.length?'*':'')+'</b></a><div class="progress"><i style="width:'+(100*v/b.cases)+'%"></i></div>'+badge(g)+'<div class="small muted" style="margin-top:6px">'+(c.running||0)+' 运行 · '+(c.pending||0)+' 待生成 · '+(c.exhausted||0)+' 终止'+(g?.reused_cases?' · '+g.reused_cases+' 历史复用':'')+'</div><div class="small muted">最近交付：'+ago(g?.latest_completion?.[0])+'</div>'}
function evalCell(g,b,m){const e=(evaluation.cohorts||[]).find(x=>x.suite===b.suite&&x.model_key===m.key&&x.track===(b.track||'vision-agent'));if(e?.full_scope_scored){const k={physics_iq:'Verified',robojudge:'Mean',pcve:'PES',phygenbench:'Overall'}[b.id],v=e.score?.metrics?.[k];if(typeof v==='number')return'<b>'+esc(k)+' '+v.toFixed(b.id==='pcve'?3:b.id==='phygenbench'?4:2)+'</b>'}if(e?.phase==='official_evaluation'&&e?.evaluation_progress?.completed)return '<span class=small>评分中 · '+e.evaluation_progress.completed+' / '+e.evaluation_progress.expected+'</span>';const labels={adapter_evaluation:'评分中',official_evaluation:'评分中',official_full_evaluation:'评分中',preparing_evaluation:'评测准备中',waiting_for_evaluation_retry:'评测待重试',waiting_for_evaluator:'等待评分',incomplete_generation:'生成未齐',stale_evaluation:'评分进程待恢复',blocked_score_provenance:'分数待校验'};const phase=e?.phase;return'<span class="small muted" title="'+esc(e?.blocker||'')+'">'+(labels[phase]||'待评测')+'</span>'}
function pcveMetricTable(b,model){const columns=[['PES',3],['TE px',2],['Mask IoU',3],['PSNR',2],['SSIM',3],['LPIPS',3],['CLIP',3],['FVD',2]],ref=evaluation.benchmark_references?.pcve,rows=[];if(!model)for(const r of ref?.rows||[])rows.push({label:r.label,kind:'论文 Table 1',metrics:r.metrics});for(const e of evaluation.cohorts||[])if(e.suite===b.suite&&e.track===(b.track||'vision-agent')&&e.full_scope_scored&&(!model||e.model_key===model)){const m=plan.models.find(m=>m.key===e.model_key);rows.push({label:m?.label||e.model_key,kind:'本地评测 · '+e.score.scope+' 条 · '+(e.score.sam2_native_postprocessing?'SAM2 原生后处理':'旧环境'),metrics:e.score.metrics})}return '<h2>完整指标 · Full 129</h2><p class="small muted">PES 为 −1 到 1 的无量纲分数；TE 单位为像素。主表仅显示 PES。全量包括 SET、ADD、DELETE；不另报 removal 子集。论文参考与本地重评注明来源。PES 校准仍在核验：已复现官方发布代码对预测与 null 的轨迹过滤不对称。</p><div class="table"><table><thead><tr><th>模型 / 方法</th>'+columns.map(([k])=>'<th>'+esc(k)+({PES:' ↑','TE px':' ↓','Mask IoU':' ↑',PSNR:' ↑',SSIM:' ↑',LPIPS:' ↓',CLIP:' ↑',FVD:' ↓'}[k]||'')+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr><td><b>'+esc(r.label)+'</b><br><span class="small muted">'+esc(r.kind)+'</span></td>'+columns.map(([k,d])=>'<td>'+(typeof r.metrics[k]==='number'?r.metrics[k].toFixed(d):'—')+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'+(ref?'<p class="small"><a href="'+esc(ref.source)+'">论文 Table 1 来源</a></p>':'')}
function modelApi(m){if(!m)return '';const health=cat?.provider_health?.models||{},name=m.api_model||m.model||m.label,h=health[name]||health['traex/'+name];if(!h?.last_success_utc)return '';return '<div class="small muted">API 最近成功：'+ago(h.last_success_utc)+'</div>'}
function home(){const chartHtml='<h2>Benchmark cost–quality</h2><div class="charts"><figure><img src="charts/physics_iq_scale.svg"><figcaption>Physics-IQ · Verified vs estimated cost</figcaption></figure><figure><img src="charts/robojudge_scale.svg"><figcaption>RoboJudge · Mean vs estimated cost</figcaption></figure><figure><img src="charts/pcve_scale.svg"><figcaption>PCVE · PES vs estimated cost</figcaption></figure><figure><img src="charts/phygenbench_scale.svg"><figcaption>PhyGenBench · Overall vs estimated cost</figcaption></figure></div>';const baselineRows=renderBaselineRows();const configured=plan.models.filter(m=>!m.pending),all=(cat.groups||[]).filter(g=>g.track==='vision-agent'&&plan.benchmarks.some(b=>b.suite===g.suite));const done=all.reduce((s,g)=>s+(g.counts?.complete||0),0),running=all.reduce((s,g)=>s+(g.counts?.running||0),0);$('headline').innerHTML='<p class="eyebrow">CODING AGENTS AS PIXEL WORLD MODELS</p><h1>PixelWorld · 主实验</h1><p class="muted">4 个 benchmark · Vision · 720p / 24 FPS · '+configured.length+' / '+plan.expected_models+' 个模型已配置</p><div class="stats"><div><b>'+done+'</b>有效交付</div><div><b>'+running+'</b>当前运行</div><div><b>'+num(configured.length*537)+'</b>已注册 case</div></div>';$('content').innerHTML='<div class="cards">'+plan.benchmarks.map(b=>{const gs=groups(b),v=gs.reduce((s,g)=>s+(g.counts?.complete||0),0),r=gs.reduce((s,g)=>s+(g.counts?.running||0),0);return'<article class="card"><span class="badge '+(r?'active':'queued')+'">'+(r?'运行中':'队列中')+'</span><h3>'+esc(b.name)+'</h3><p class="muted small">'+esc(b.spec)+'</p><div class="num">'+v+' <span class="muted small">/ '+(b.cases*configured.length)+'</span></div><p class="small muted">'+b.cases+' prompts / model</p><a href="'+b.page+'">查看模型与视频 →</a></article>'}).join('')+'</div>'+chartHtml+'<h2>模型 × Benchmark</h2><div class="table"><table><thead><tr><th>模型 · Vision</th>'+plan.benchmarks.map(b=>'<th>'+esc(b.short)+'</th>').join('')+'</tr></thead><tbody>'+baselineRows+plan.models.map(m=>'<tr><td><b>'+esc(m.label)+'</b>'+modelApi(m)+'</td>'+plan.benchmarks.map(b=>'<td>'+cell(groups(b).find(g=>g.model_key===m.key),b,m)+'<div class="small">评测：'+evalCell(groups(b).find(g=>g.model_key===m.key),b,m)+'</div></td>').join('')+'</tr>').join('')+'</tbody></table></div><p class="small muted">新增模型按同一协议补入矩阵。生成完成后进入独立评测；未完成评测的分数不显示为零。参考分数保留原评测口径；本地重评标注 judge。PCVE 的预测/null 过滤不对称，Table 1 对照仍在核验。PhyGenBench 使用 GPT-5.5 adaptation。带 * 的交付含按授权补跑，原始记录保留。API 响应时间汇总该模型全部实验。</p><p><a href="analyses.html">分析实验进度 →</a> · <a href="https://siyuanmacs.github.io/physics-iq-pixel-preview/">历史实验 / Legacy →</a></p>'}
async function detail(path,preferLive=false){let d;try{d=await load(path,false,true,preferLive)}catch(e){$('detail').innerHTML='<div class=notice>详情暂不可用：'+esc(e.message)+'。发布队列会继续同步。</div>';return}const media=x=>asset(x,d._asset_base);const playing=$('detail')?.querySelector('video');if(playing&&!playing.paused)return;const diag=d.diagnostics||{};let text='<section class="panel detail"><div class="toolbar"><h2 style="margin:0">'+esc(d.case_id)+' · Attempt '+d.attempt+'</h2><span class="badge '+(d.delivery_status==='complete'?'complete':d.delivery_status==='running'?'active':'failed')+'">'+esc(d.delivery_status)+'</span></div>'+(d.reused?'<p class="small muted">历史复用 · '+esc(d.provenance?.source_suite)+' · 原始运行环境 '+esc(d.provenance?.original_filesystem_policy)+'</p>':'')+'<div class="stats"><div><b>'+tok(d.input_tokens)+'</b>Input tokens</div><div><b>'+tok(d.output_tokens)+'</b>Output tokens</div><div><b>'+mins(d.duration_seconds)+'</b>本次耗时</div><div><b>'+d.candidates.length+'</b>保存候选</div></div><details open><summary>任务指令</summary><p>'+esc(d.prompt)+'</p></details>';if(d.source_video)text+='<details><summary>输入源视频</summary><video controls preload="none" src="'+media(d.source_video)+'"></video></details>';else if(d.first_frame)text+='<details><summary>输入首帧</summary><img class="inputimage" src="'+media(d.first_frame)+'"></details>';if(d.trace_archive)text+='<p><a href="'+esc(d.trace_archive)+'" target="_blank" rel="noopener">下载完整脱敏 Trace →</a></p>';if(d._live_source)text+='<p class="small muted">实时详情 · HF 归档仍在同步</p>';if(d.candidate_history_pending&&d.candidates.length)text+='<p class="small muted">当前视频已就绪，历史候选预览正在补齐。</p>';if(d.native_output_present&&!d.candidates.length)text+='<div class="notice">原生 RGB 已保存，正在生成可播放预览。</div>';if(d.media_export_errors?.length)text+='<details><summary>预览生成记录</summary><pre>'+esc(JSON.stringify(d.media_export_errors,null,2))+'</pre></details>';if(!d.candidates.length&&!d.native_output_present)text+='<div class="notice">尚未保存可播放候选。下面展示当前工具记录与交付诊断。</div>';text+='<div class="versions">'+d.candidates.map(c=>'<article><p><b>'+esc(c.label)+'</b> <span class="small muted">'+esc(c.utc||'')+'</span></p>'+(c.preview_mp4?'<video controls preload="none" poster="'+media(c.poster)+'" src="'+media(c.preview_mp4)+'"></video>':'<img class="inputimage" src="'+media(c.poster)+'">')+(c.code?'<details><summary>生成代码</summary><pre>'+esc(c.code)+'</pre></details>':'')+'</article>').join('')+'</div><details '+(d.delivery_status==='complete'?'':'open')+'><summary>交付与失败诊断</summary><pre>'+esc(JSON.stringify({diagnostics:diag,validation:d.validation,budget_exhausted:d.budget_exhausted},null,2))+'</pre></details><details><summary>工具与执行记录 · '+d.events.length+' 条</summary>'+d.events.map(e=>'<details><summary>'+esc(e.kind)+' · '+esc(e.utc||'')+'</summary>'+(e.command?'<pre>'+esc(e.command)+'</pre>':'')+(e.aggregated_output?'<pre>'+esc(e.aggregated_output)+'</pre>':'')+(e.text?'<pre>'+esc(e.text)+'</pre>':'')+(e.images||[]).map(i=>'<img class="inputimage" src="'+media(i)+'">').join('')+'</details>').join('')+'</details></section>';$('detail').innerHTML=text;lastDetailKey=path;retryMedia($('detail'))}
async function benchmark(){const query=new URLSearchParams(location.search),base=plan.benchmarks.find(x=>x.id===document.body.dataset.benchmark),b={...base,suite:query.get('suite')||base.suite,track:query.get('track')||'vision-agent'};if(b.suite!==base.suite){try{const a=await load('analysis_progress.json');const c=a.conditions.find(x=>x.id===b.suite);if(c){b.name=c.title;b.spec=c.output_text||b.spec;b.cases=c.cases}}catch(e){}}const gs=groups(b),model=query.get('model');if(b.suite!==base.suite){const meta=cat.suites?.[b.suite]||{};b.name=meta.title||b.name;b.spec=meta.output_text||b.spec;if(gs[0]?.cases_total)b.cases=gs[0].cases_total}$('headline').innerHTML='<p class="eyebrow">EXPERIMENT · '+esc(b.track)+'</p><h1>'+esc(b.name)+'</h1><p class="muted">'+esc(b.spec)+' · '+b.cases+' cases / model</p><p><a href="index.html">← 主实验总览</a></p>';if(!model){$('content').innerHTML='<div class="table"><table><thead><tr><th>模型</th><th>生成进度</th><th>Input 均值</th><th>Output 均值</th><th>耗时均值</th><th>评测</th></tr></thead><tbody>'+plan.models.filter(m=>b.suite===base.suite||gs.some(g=>g.model_key===m.key)).map(m=>{let g=gs.find(x=>x.model_key===m.key);return'<tr><td><a href="'+groupLink(b,m.key)+'">'+esc(m.label)+'</a>'+modelApi(m)+'</td><td>'+cell(g,b,m)+'</td><td>'+tok(g?.mean_input_tokens)+'</td><td>'+tok(g?.mean_output_tokens??g?.mean_output_tokens_cached)+'</td><td>'+mins(g?.mean_duration_seconds)+'</td><td>'+evalCell(g,b,m)+'</td></tr>'}).join('')+'</tbody></table></div><p class="small muted">均值按有效交付的首次成功 attempt 统计；未报告 usage 显示为 —。</p>'+(b.id==='pcve'?pcveMetricTable(b):'');return}const g=gs.find(x=>x.model_key===model),m=plan.models.find(x=>x.key===model);if(!g){$('content').innerHTML='<div class="notice">'+esc(m?.label||model)+' 尚未进入已配置队列。</div>';return}const data=await load(g.path,false,false,true);const histories=Object.entries(data.cases||{}).sort(([a],[b])=>a.localeCompare(b));$('content').innerHTML='<h2>'+esc(m?.label||model)+' · '+esc(b.track)+'</h2><div class="stats"><div><b>'+(g.counts?.complete||0)+' / '+b.cases+'</b>有效交付</div><div><b>'+(g.counts?.running||0)+'</b>运行中</div><div><b>'+tok(g.mean_input_tokens)+'</b>Input 均值</div><div><b>'+tok(g.mean_output_tokens??g.mean_output_tokens_cached)+'</b>Output 均值</div><div><b>'+mins(g.mean_duration_seconds)+'</b>耗时均值</div></div><p>'+badge(g)+' <span class="small muted">'+histories.length+' 个样本已有详情</span></p><div class="casegrid">'+histories.map(([cid,h])=>{const a=h.slice().sort((a,b)=>Number(b.reused)-Number(a.reused)||Number(b.status==='complete')-Number(a.status==='complete')||b.attempt-a.attempt)[0];return'<button class="case '+(selected===cid?'selected':'')+'" data-case="'+esc(cid)+'">'+(a.poster&&a.candidate_count?'<img loading="lazy" src="'+asset(a.poster,a.hf_detail_ready===false&&cat?.live_origin?cat.live_origin:data._asset_base)+'">':'<div class="empty">'+esc(a.status)+'</div>')+'<div class="info"><b>'+esc(cid)+'</b><br>'+esc(a.status)+' · '+h.length+' 次记录<br>'+tok(a.output_tokens)+' output · '+a.candidate_count+' 候选</div></button>'}).join('')+'</div>';for(const el of document.querySelectorAll('[data-case]'))el.onclick=()=>{selected=el.dataset.case;showSelected()};
async function showSelected(){let h=(data.cases||{})[selected];if(!h)return;h=h.slice().sort((a,b)=>Number(b.reused)-Number(a.reused)||Number(b.status==='complete')-Number(a.status==='complete')||b.attempt-a.attempt);$('attempts').innerHTML='<label class="small muted">运行记录 </label><select id="attempt-select">'+h.map(a=>'<option value="'+esc(a.detail)+'">Attempt '+a.attempt+' · '+esc(a.status)+'</option>').join('')+'</select>';$('attempt-select').onchange=()=>{const item=h.find(a=>a.detail===$('attempt-select').value);detail(item.detail,item.hf_detail_ready===false||item.status==='running')};await detail(h[0].detail,h[0].hf_detail_ready===false||h[0].status==='running')}if(selected)await showSelected()}
function renderBaselineRows(){return(plan.video_baselines||[]).map(m=>'<tr class="baseline"><td><b>'+esc(m.label)+'</b><br><span class="badge">video baseline</span></td>'+plan.benchmarks.map(b=>{const e=m.scores?.[b.id];const progress=m.benchmark_progress?.[b.id]||(b.id==='pcve'?m.progress:null);if(typeof e?.value!=='number'){if(progress){const labels={waiting_for_free_gpu_group:'等待空闲 GPU',loading_model:'加载模型',smoke_generating:'首条 smoke 生成中',smoke_running:'smoke 运行中',smoke_failed:'smoke 待恢复',generation_running:'生成中',generated:'等待评分',evaluating:'评分中',finished:'已完成',generation_failed:'生成任务待恢复',evaluation_failed:'评测任务待恢复'};let status=esc(labels[progress.phase]||progress.phase);if(progress.evaluation_total)status+=' · '+(progress.evaluation_completed||0)+' / '+progress.evaluation_total;return'<td><b>本地 '+(progress.completed||0)+' / '+progress.total+'</b><br><span class=small>'+status+'</span></td>'}return'<td>待评测 / 待核实</td>'}const digits=b.id==='phygenbench'?4:b.id==='physics_iq'?2:3;const note=e.kind==='matched_rerun'?(e.judge+' · '+e.cases+' cases'):e.kind==='calibration_subset'?('本地校准 · '+e.cases+' cases，非全量'):'参考结果';return'<td title="'+esc(e.note||'')+'"><b>'+e.value.toFixed(digits)+'</b><br><span class="small muted">'+esc(note)+'</span></td>'}).join('')+'</tr>').join('')}
async function poll(){try{cat=await load('catalogue.json',false,false,true);plan=await load('experiment_plan.json');try{evaluation=await load('evaluation.json',false,false,true)}catch(e){evaluation={cohorts:[]}}$('sync').textContent='数据更新：'+ago(cat.updated_utc)+' · '+new Date(cat.updated_utc).toLocaleTimeString();if(document.body.dataset.benchmark)await benchmark();else home()}catch(e){$('sync').textContent='同步等待 · '+e.message}}poll();setInterval(poll,15000)})();'''

BENCHMARKS = [
    ('physics_iq','Physics-IQ Verified','Physics-IQ',198,'physics_iq_720p24fps','physics_iq_baseline.html','1280×720 · 24 FPS · 5 秒 · I2V'),
    ('robojudge','RoboJudge shared-50','RoboJudge',50,'robojudge_main720p24fps','robojudge.html','保留比例，短边 720 · 24 FPS · 5 秒 · I2V'),
    ('pcve','PCVE-RigidBench','PCVE',129,'pcve_standard720p24fps','pcve_rigid.html','1280×720 · 24 FPS · 4 秒 · Video Editing'),
    ('phygenbench','PhyGenBench','PhyGenBench',160,'phygenbench_t2v_main720p24fps','phygen_pixelspace.html','1280×720 · 24 FPS · 5 秒 · T2V'),
]


def build(bundle: Path, checkout: Path):
    meta=json.loads((bundle/'bundle.json').read_text());models={}
    for paths in meta['configs'].values():
        config=json.loads((bundle/paths['full']).read_text())
        for model in config['models']:
            models[model['key']]={'key':model['key'],'label':model.get('display_name',model['model'].split('/')[-1]),'api_model':model['model']}
    order=['gpt61-sol','gpt6-astra','gpt56-sol','gpt56-terra','gpt56-luna','deepseek-v41','seed21-pro','awaiting-model']
    models={k:models[k] for k in sorted(models,key=lambda k: order.index(k) if k in order else 999)}
    ready=json.loads((bundle/'READINESS.json').read_text())
    expected=max(ready.get('model_slots_expected',len(models)),len(models))
    if len(models)<expected:models['awaiting-model']={'key':'awaiting-model','label':'第六个模型 · 待确认','pending':True}
    plan={'expected_models':expected,'models':list(models.values()),'benchmarks':[dict(zip(('id','name','short','cases','suite','page','spec'),b))for b in BENCHMARKS]}
    from tools.baseline_data import video_baselines
    plan['video_baselines']=video_baselines(bundle)
    root=checkout/'pixelworld';root.mkdir(exist_ok=True)
    (root/'experiment_plan.json').write_text(json.dumps(plan,ensure_ascii=False,indent=2))
    (root/'formal.css').write_text(CSS)
    (root/'formal.js').write_text(JS)
    shell='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PixelWorld · Live Experiments</title><link rel="stylesheet" href="formal.css?v=20261117"></head><body DATA><header><nav><strong><a href="index.html">PixelWorld</a></strong><span><a href="index.html">主实验</a><a href="analyses.html">分析</a><a href="https://huggingface.co/datasets/HuggingFriends/PixelWorld">视频与记录</a><a href="https://huggingface.co/datasets/HuggingFriends/PixelWorld/tree/main/traces">完整 Trace</a><a href="https://github.com/SiYuanJasperMa/PixelWorld">GitHub</a><a href="https://siyuanmacs.github.io/physics-iq-pixel-preview/">Legacy</a></span></nav></header><main><div id="headline"></div><p class="small muted" id="sync">正在加载实时数据…</p><div id="content"></div><div id="attempts"></div><div id="detail"></div><footer>新运行：Vision · Codex 0.169.0 · case-only-v1 · 1M output tokens / attempt（新 attempt）· 最多 5 次真实 attempt。已完成的 100k 交付保留原始记录。</footer></main><script src="formal.js?v=20261118-evaluation"></script></body></html>'''
    version=hashlib.sha256(JS.encode()).hexdigest()[:12]
    shell=shell.replace('formal.js?v=20261118-evaluation','formal.js?v='+version)
    paths=['index.html','pixelworld-index.html']
    for name in paths:(root/name).write_text(shell.replace('DATA',''))
    for b in BENCHMARKS:
        (root/b[5]).write_text(shell.replace('DATA','data-benchmark="'+b[0]+'"'))
    for name in ['physics_iq_resolution.html','physics_iq_512w24fps.html']:
        (root/name).write_text(shell.replace('DATA','data-benchmark="physics_iq"'))
    (root/'phygenbench.html').write_text(shell.replace('DATA','data-benchmark="phygenbench"'))
    analysis='''<p class="eyebrow">ANALYSIS · TWO MODELS</p><h1>分析实验</h1><p class="muted">GPT-6.1-Sol · DeepSeek-V4.1-Flash</p><div class="table"><table><tr><th>问题</th><th>配置</th><th>当前阶段</th></tr><tr><td>Text vs Vision</td><td>四个 benchmark，补 Text；共享 Vision 主实验</td><td>准备 / 主实验优先</td></tr><tr><td>分辨率</td><td>Physics-IQ：480p / 720p / 1080p，24 FPS</td><td>准备</td></tr><tr><td>FPS</td><td>Physics-IQ：12 / 24 / 48 FPS，720p</td><td>准备</td></tr><tr><td>Thinking</td><td>原生支持的较低 / High / 较高档位</td><td>核对模型支持</td></tr><tr><td>初始化</td><td>PhyGenBench：T2V / QwenInit-I2V × Text / Vision</td><td>准备首帧与队列</td></tr><tr><td>自主修订与成本</td><td>首个有效候选 / 最终候选；真实调用与 token</td><td>复用已记录轨迹</td></tr></table></div><p><a href="index.html">← 主实验</a></p>'''
    from tools.build_analysis_dashboard import build as build_analysis
    if not (root/'analysis_progress.json').is_file():
        build_analysis(root,bundle)
    return plan


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--bundle',type=Path,required=True);p.add_argument('--checkout',type=Path,required=True)
    args=p.parse_args();plan=build(args.bundle.resolve(),args.checkout.resolve())
    print(json.dumps({'configured_models':len([m for m in plan['models']if not m.get('pending')]),'benchmarks':len(plan['benchmarks'])}))
